import{_ as t,o as a,c as e,a2 as r}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"副本服功能介紹","description":"副本服特殊功能的相關介紹。","frontmatter":{"title":"副本服功能介紹","description":"副本服特殊功能的相關介紹。"},"headers":[],"relativePath":"dungeon/function/index.md","filePath":"dungeon/function.md"}'),l={name:"dungeon/function/index.md"};function o(n,i,s,h,c,d){return a(),e("div",null,[...i[0]||(i[0]=[r('<h1 id="功能介紹" tabindex="-1">功能介紹 <a class="header-anchor" href="#功能介紹" aria-label="Permalink to &quot;功能介紹&quot;">​</a></h1><h2 id="副本幣轉換" tabindex="-1">副本幣轉換 <a class="header-anchor" href="#副本幣轉換" aria-label="Permalink to &quot;副本幣轉換&quot;">​</a></h2><p>將副本幣轉換為一般伺服使用的金錢</p><h3 id="操作說明" tabindex="-1">操作說明 <a class="header-anchor" href="#操作說明" aria-label="Permalink to &quot;操作說明&quot;">​</a></h3><ol><li>請輸入<code>/bs</code>點擊此按鈕(有500、2000、20000三種面額，寄出後副本幣至少要留500)<br><img src="https://i.imgur.com/IJJ3rAR.png" style="width:50%;"></li><li>當你看到此訊息後 即可回到主服或設施服<br><img src="https://i.imgur.com/Z9khgQy.png" style="width:80%;"></li><li>回來主服或設施服之後 你會看到一條信件訊息<br><img src="https://i.imgur.com/Uy0s6d8.png" style="width:80%;"></li><li>輸入<code>/mail</code>後 點擊此訊息 即可將信件刪除 並將寄出的金額領出<br><img src="https://i.imgur.com/u6QAO0f.png" style="width:80%;"></li></ol><h3 id="備註" tabindex="-1">備註 <a class="header-anchor" href="#備註" aria-label="Permalink to &quot;備註&quot;">​</a></h3><ul><li>只有在主服、設施服、資源服及大廳服才能領取金錢</li></ul><h2 id="副本懸賞系統" tabindex="-1">副本懸賞系統 <a class="header-anchor" href="#副本懸賞系統" aria-label="Permalink to &quot;副本懸賞系統&quot;">​</a></h2><p>如果你希望有玩家去追殺指定玩家，可以懸賞該玩家<br> 任何玩家擊殺被懸賞者一定次數後，將可獲得金錢獎勵</p><h3 id="操作說明-1" tabindex="-1">操作說明 <a class="header-anchor" href="#操作說明-1" aria-label="Permalink to &quot;操作說明&quot;">​</a></h3><ol><li>至水果攤大叔購買懸賞單(1張200元)<br><img src="https://i.imgur.com/pA8Ta3D.png" style="width:80%;"></li><li>至2樓懸賞牆，拿著懸賞單對告示牌點右鍵<br><img src="https://i.imgur.com/uFIqo7A.png" style="width:80%;"></li><li>選擇想要被懸賞的人<br><img src="https://i.imgur.com/HhC3XyG.png" style="width:80%;"></li><li>跳出此通知代表您已完成懸賞<br><img src="https://i.imgur.com/kY2A7J7.png" style="width:80%;"></li></ol><h3 id="備註-1" tabindex="-1">備註 <a class="header-anchor" href="#備註-1" aria-label="Permalink to &quot;備註&quot;">​</a></h3><ul><li>只有在副本服內的玩家才可以被懸賞</li></ul>',13)])])}const p=t(l,[["render",o]]);export{u as __pageData,p as default};
